    -- Get content behavior scores
    SELECT cntsimscore, cntuniqscore, cntdiverseval
    INTO v_cntsimscore, v_cntuniqscore, v_cntdiverseval
    FROM contentbehavior
    WHERE cntref = p_cntref;

    -- Get messaging analysis scores
    SELECT msgsimscore, convnatval, langsoph, txtuniq, topiccoh
    INTO v_msgsimscore, v_convnatval, v_langsoph, v_txtuniq, v_topiccoh
