CREATE OR REPLACE FUNCTION calculate_csi(p_cntref CHARACTER(12))
RETURNS NUMERIC AS $$
DECLARE
    v_cntuniqscore NUMERIC;
    v_mediareratio NUMERIC;
    v_txtuniq NUMERIC;
    v_authenscore NUMERIC;
    v_convnatval NUMERIC;
    v_cms NUMERIC;
    v_cas NUMERIC;
    v_csi NUMERIC;
BEGIN
    -- Get content behavior scores
    SELECT COALESCE(cntuniqscore, 0), COALESCE(mediareratio, 0)
    INTO v_cntuniqscore, v_mediareratio
    FROM contentbehavior
    WHERE cntref = p_cntref;

    -- Get messaging analysis scores for txtuniq and convnatval
    SELECT COALESCE(txtuniq, 0), COALESCE(convnatval, 0)
    INTO v_txtuniq, v_convnatval
    FROM messaginganalysis ma
    JOIN contentbehavior cb ON cb.cntref = ma.msgcntref
    WHERE cb.cntref = p_cntref;

    -- Get moderation action score for authenscore
    SELECT COALESCE(authenscore, 0)
    INTO v_authenscore
    FROM moderationaction md
    JOIN contentbehavior cb ON cb.cntref = md.macntref
    WHERE cb.cntref = p_cntref;

    -- Calculate CMS (Content Manipulation Score)
    v_cms := 0.4 * (1 - v_cntuniqscore) + 0.3 * v_mediareratio + 0.3 * (1 - v_txtuniq);

    -- Calculate CAS (Content Authenticity Score)
    v_cas := 0.3 * v_authenscore + 0.3 * v_cntuniqscore + 0.4 * v_convnatval;

    -- Calculate CSI
    v_csi := 0.7 * (1 - v_cms) + 0.3 * v_cas;

    RETURN v_csi;
EXCEPTION WHEN OTHERS THEN
    RAISE WARNING 'Error calculating CSI for %: %', p_cntref, SQLERRM;
    RETURN NULL;
END;
$$ LANGUAGE plpgsql;

